//! Parity tests against fixtures/rust-parity.json (generated by
//! python/gen_parity.py from the Python library). Tolerances: 1e-8
//! relative for algebraic quantities, looser for iterative solves
//! as marked per test (the Phase 8 plan tolerance classes).

use ccr::activity::{gamma_nrtl, gamma_uniquac};
use ccr::columns::{absorber, rigorous_tower, shortcut, RaoultThermo};
use ccr::eos::{CubicEOS, EosKind};
use ccr::exchangers::{f_factor_1_2, hx_rate_ua};
use ccr::flash::flash_tp;
use ccr::flash3::{extraction, flash3_tp};
use ccr::reactors::{reactor_cstr, reactor_equilibrium, reactor_gibbs,
                    reactor_pfr, reactor_stoich, ThermoRx};
use ccr::solids::{crusher_bond, cyclone_d50};
use ccr::thermo::{Stream, ThermoEOS};
use ccr::unifac::gamma_unifac;
use ccr::units::{compressor, valve};

fn close(a: f64, b: f64, tol: f64) -> bool {
    (a - b).abs() <= tol * (1.0 + b.abs())
}
fn alkane_eos() -> CubicEOS {
    CubicEOS::new(EosKind::PR, vec![190.6, 305.3, 369.8],
                  vec![4.599e6, 4.872e6, 4.248e6], vec![0.011, 0.099, 0.152])
}
fn cp3() -> Vec<Vec<f64>> {
    vec![vec![35.8, 0.0, 0.0, 0.0], vec![52.5, 0.0, 0.0, 0.0],
         vec![73.6, 0.0, 0.0, 0.0]]
}

#[test]
fn eos_parity() {
    let eos = alkane_eos();
    let lp = eos.ln_phi(&[0.5, 0.3, 0.2], 300.0, 2.0e6, true);
    let exp = [-0.022725243480800406, -0.16577842804511536, -0.28594591586253926];
    for i in 0..3 { assert!(close(lp[i], exp[i], 1e-9), "lnphi {}", i); }
}

#[test]
fn flash_parity() {
    let eos = alkane_eos();
    let res = flash_tp(&[0.5, 0.3, 0.2], 250.0, 2.0e6, |x, y, t, p| eos.k_values(x, y, t, p));
    assert!(close(res.psi, 0.7244637781881276, 1e-8));
    let ex = [0.12854198357073202, 0.3742533578311866, 0.4972046585980814]; let ey = [0.6412770955431739, 0.27175912683334, 0.08696377762348595];
    for i in 0..3 {
        assert!(close(res.x[i], ex[i], 1e-8), "x {}", i);
        assert!(close(res.y[i], ey[i], 1e-8), "y {}", i);
    }
}

#[test]
fn activity_parity() {
    let tau = vec![vec![0.0, 1.5, 0.5], vec![0.8, 0.0, 0.2], vec![0.3, 0.1, 0.0]];
    let alp = vec![vec![0.0, 0.3, 0.3], vec![0.3, 0.0, 0.3], vec![0.3, 0.3, 0.0]];
    let g = gamma_nrtl(&[0.3, 0.3, 0.4], &tau, &alp);
    let e = [1.781336480924417, 1.4446647334791982, 1.0145627982972485];
    for i in 0..3 { assert!(close(g[i], e[i], 1e-10), "nrtl {}", i); }
    let tau_u = vec![vec![0.0, 120.0, 300.0], vec![-80.0, 0.0, 150.0], vec![50.0, -40.0, 0.0]];
    let gu = gamma_uniquac(&[0.3, 0.3, 0.4], &[2.5, 1.8, 3.1], &[2.2, 1.6, 2.8], &tau_u);
    let eu = [0.0001607107545839085, 2.708350766402224, 6.153786854994877e-07];
    for i in 0..3 { assert!(close(gu[i], eu[i], 1e-10), "uniquac {}", i); }
}

#[test]
fn unifac_parity() {
    let nu = vec![vec![1.0, 1.0, 1.0, 0.0], vec![0.0, 0.0, 0.0, 1.0]];
    let rk = vec![0.9011, 0.6744, 1.0, 0.92];
    let qk = vec![0.848, 0.540, 1.2, 1.40];
    let a = vec![vec![0.0, 0.0, 986.5, 1318.0], vec![0.0, 0.0, 986.5, 1318.0],
                 vec![156.4, 156.4, 0.0, 353.5], vec![300.0, 300.0, -229.1, 0.0]];
    let g = gamma_unifac(&[0.5, 0.5], 298.15, &nu, &rk, &qk, &a);
    let e = [1.2037407930848445, 1.4967445314900478];
    for i in 0..2 { assert!(close(g[i], e[i], 1e-9), "unifac {}", i); }
}

#[test]
fn ps_and_units_parity() {
    let th = ThermoEOS::new(alkane_eos(), cp3());
    let (s0, _) = th.mixture_entropy(&[0.5, 0.3, 0.2], 250.0, 2.0e6);
    let (t, res) = th.flash_ps(&[0.5, 0.3, 0.2], 2.0e6, s0);
    assert!(close(t, 249.9999999254942, 1e-6), "ps T {}", t);
    assert!(close(res.psi, 0.7244637773529584, 1e-6));
    let feed = Stream::new(vec![50.0, 30.0, 20.0], 300.0, 0.5e6);
    let (out, w) = compressor(&th, &feed, 2.0e6, 0.75);
    assert!(close(out.t, 410.11761384797865, 1e-6), "comp T");
    assert!(close(w, 502238.5460490509, 1e-6), "comp W");
    let v = valve(&th, &Stream::new(vec![50.0, 30.0, 20.0], 300.0, 3.0e6), 1.0e6);
    assert!(close(v.t, 280.53764769865666, 1e-6), "valve T");
}

fn wgs_rx() -> ThermoRx {
    let eos = CubicEOS::new(EosKind::PR, vec![132.9, 647.1, 304.2, 33.2],
        vec![3.496e6, 22.064e6, 7.38e6, 1.313e6], vec![0.048, 0.345, 0.225, -0.216]);
    let cp = vec![vec![29.1, 0.0, 0.0, 0.0], vec![33.6, 0.0, 0.0, 0.0],
                  vec![37.1, 0.0, 0.0, 0.0], vec![28.8, 0.0, 0.0, 0.0]];
    ThermoRx { th: ThermoEOS::new(eos, cp),
        hf: vec![-110530.0, -241820.0, -393510.0, 0.0],
        gf: vec![-137170.0, -228590.0, -394360.0, 0.0] }
}

#[test]
fn reactors_parity() {
    let rx = wgs_rx();
    let feed = Stream::new(vec![100.0, 100.0, 0.0, 0.0], 1000.0, 1.0e5);
    let nu = vec![vec![-1.0, -1.0, 1.0, 1.0]];
    let (eq, _) = reactor_equilibrium(&rx, &feed, &nu, "isothermal", Some(1000.0), None);
    assert!(close(eq.flows[2], 48.544627132978725, 1e-5), "eq extent {}", eq.flows[2]);
    let hf = rx.hf.clone(); let gf = rx.gf.clone();
    let (gb, _) = reactor_gibbs(&rx, &feed,
        &[vec![1.0, 0.0, 1.0], vec![0.0, 2.0, 1.0], vec![1.0, 0.0, 2.0], vec![0.0, 2.0, 0.0]],
        |i, t| hf[i] - t * (hf[i] - gf[i]) / 298.15, 1000.0);
    assert!(close(gb.flows[2], 48.5447465449351, 1e-4), "gibbs extent {}", gb.flows[2]);
    let (st, _) = reactor_stoich(&rx, &Stream::new(vec![100.0, 100.0, 0.0, 0.0], 700.0, 1.0e5),
        &nu, &[0.5], &[0], "adiabatic", None, None);
    assert!(close(st.t, 1009.8139984504087, 1e-6), "stoich T");
    // Kinetics on the alkane thermo (labelled synthetic A -> B).
    let rxk = ThermoRx { th: ThermoEOS::new(alkane_eos(), cp3()),
        hf: vec![0.0; 3], gf: vec![0.0; 3] };
    let feedk = Stream::new(vec![100.0, 0.0, 0.0], 300.0, 1.0e5);
    let vm = rxk.th.molar_volume(&[1.0, 0.0, 0.0], 300.0, 1.0e5, true);
    let vol = 10.0 * 100.0 * vm;
    let nuk = vec![vec![-1.0, 1.0, 0.0]];
    let (oc, _) = reactor_cstr(&rxk, &feedk, &nuk, |c, _t, _p| vec![0.1 * c[0]], vol, 300.0);
    assert!(close(1.0 - oc.flows[0] / 100.0, 0.5006452992919077, 1e-4), "cstr X");
    let (op, _) = reactor_pfr(&rxk, &feedk, &nuk, |c, _t, _p| vec![0.1 * c[0]], vol, 300.0);
    assert!(close(1.0 - op.flows[0] / 100.0, 0.6328087581537234, 1e-4), "pfr X");
}

fn alkane_thermo() -> RaoultThermo {
    // Antoine (ln, kPa, K) constants of the distillation-game
    // ALKANES mixture, supplied here as test inputs.
    let abc = [(14.2706, 2730.9, -26.806), (14.3314, 3004.3, -33.111),
               (14.3748, 3237.52, -40.249)];
    let mut psat: Vec<Box<dyn Fn(f64) -> f64>> = Vec::new();
    for (a, b, c) in abc {
        psat.push(Box::new(move |t: f64| 1000.0 * (a - b / (t + c)).exp()));
    }
    let hl: Vec<Box<dyn Fn(f64) -> f64>> = (0..3).map(|_| Box::new(|t: f64| 150.0 * (t - 300.0)) as Box<dyn Fn(f64) -> f64>).collect();
    let hv: Vec<Box<dyn Fn(f64) -> f64>> = (0..3).map(|_| Box::new(|t: f64| 30000.0 + 100.0 * (t - 300.0)) as Box<dyn Fn(f64) -> f64>).collect();
    RaoultThermo { psat, hl, hv }
}

#[test]
fn columns_parity() {
    let th = alkane_thermo();
    let sc = shortcut(&[0.40, 0.30, 0.30], 10.0, 0, 1, 0.99, 0.99, &th, 150e3, 1.3);
    assert!(close(sc.nmin, 9.17653923017978, 1e-9), "Nmin");
    assert!(close(sc.rmin, 1.0493986257981782, 1e-9), "Rmin");
    assert!(close(sc.n, 20.245003643771952, 1e-9), "N");
    let tw = rigorous_tower(&[0.40, 0.30, 0.30], 10.0, 12, 6, 4.0, 5.0, 150e3, &th);
    let xt = [0.9106039997328764, 0.08914693991215676, 0.00024906035496687225]; let xb = [0.021476562033430173, 0.47854462765597894, 0.4999788103105909];
    let nst = tw.x.len();
    for i in 0..3 {
        assert!(close(tw.x[nst - 1][i], xt[i], 1e-7), "tower x_top {}", i);
        assert!(close(tw.x[0][i], xb[i], 1e-7), "tower x_bot {}", i);
    }
    assert!(close(tw.t[nst - 1], 323.6732013517179, 1e-7), "tower T_top");
    assert!(close(tw.q_reboiler, 252562.8169505529, 1e-6), "Qr");
    assert!(close(tw.q_condenser, 261053.15675928735, 1e-6), "Qc");
}

#[test]
fn absorber_parity() {
    // Constant-K thermo: K = [2, 1e7, 0] as in the Python fixture.
    struct CThermo;
    let th = RaoultThermo {
        psat: vec![Box::new(|_t| 2.0), Box::new(|_t| 1e7), Box::new(|_t| 0.0)],
        hl: vec![Box::new(|_t| 0.0), Box::new(|_t| 0.0), Box::new(|_t| 0.0)],
        hv: vec![Box::new(|_t| 0.0), Box::new(|_t| 0.0), Box::new(|_t| 0.0)],
    };
    let _ = CThermo;
    // RaoultThermo K = psat / P: use P = 1 so psat values are the K's.
    let ab = absorber(&[100.0, 100.0, 0.0], &[100.0, 0.0, 0.0], 5, 1.0, 350.0, &th);
    let eg = [0.6362909787974578, 0.36370902120254217, 0.0]; let el = [0.9999998004386365, 1.9956136368402613e-07, 0.0];
    for i in 0..3 {
        assert!(close(ab.y[4][i], eg[i], 1e-6), "abs gas {}", i);
        assert!(close(ab.x[0][i], el[i], 1e-6), "abs liq {}", i);
    }
}

#[test]
fn flash3_extraction_parity() {
    let tau = vec![vec![0.0, 3.5, 3.2], vec![1.2, 0.0, 0.1], vec![1.1, 0.1, 0.0]];
    let alp = vec![vec![0.0, 0.3, 0.3], vec![0.3, 0.0, 0.3], vec![0.3, 0.3, 0.0]];
    let g = |x: &[f64]| gamma_nrtl(x, &tau, &alp);
    let f3 = flash3_tp(&[0.3, 0.2, 0.5], 101325.0, &g, &[71288.0, 35644.0, 31683.0]);
    assert!(close(f3.beta_v, 3.0637728087289646e-18, 1e-5), "bV {}", f3.beta_v);
    assert!(close(f3.beta_2, 0.15114633120724683, 1e-5), "b2");
    let ex1 = [0.17923435550398084, 0.23521797141859904, 0.5855476730774202]; let ex2 = [0.9774190299657302, 0.005494311037504809, 0.017086658996765033];
    for i in 0..3 {
        assert!(close(f3.x1[i], ex1[i], 1e-4), "x1 {}", i);
        assert!(close(f3.x2[i], ex2[i], 1e-4), "x2 {}", i);
    }
    let ex = extraction(&[60.0, 40.0, 0.0], &[0.0, 0.0, 100.0], 5, &g);
    // Balance tolerance 5e-3 mol/s on 200 mol/s: the coupled LM
    // solve stalls at ~2e-3 mol/s (1e-5 relative) where the
    // log-fugacity residuals of the trace solute dominate its
    // Jacobian accuracy -- solver precision, not a leak (the
    // raffinate and extract flows themselves match the Python to
    // ~1e-3 relative, inside the programme's 0.002 mole-fraction
    // composition tolerance).
    assert!(ex.balance_residual < 5e-3, "extraction balance {}", ex.balance_residual);
    let er = [30.10158683396978, -0.0013785593155037474, 0.7454710899742452];
    // Absolute 3e-3 mol/s: the trace-solute raffinate flow is
    // -0.0014 in the Python (its one-sweep Jacobi lag) and +7e-7
    // here; both are zero within solver precision.
    for i in 0..3 {
        assert!((ex.raffinate_flows[i] - er[i]).abs() < 3e-3, "raff {}", i);
    }
}

#[test]
fn hx_solids_parity() {
    let (q, _, _) = hx_rate_ua(1000.0, 1000.0, 1000.0, 400.0, 300.0, true);
    assert!(close(q, 50000.0, 1e-10));
    assert!(close(f_factor_1_2(400.0, 350.0, 300.0, 340.0), 0.8769258506515542, 1e-9));
    let (e, _) = crusher_bond(10.0, 10000.0, 1000.0, 13.0);
    assert!(close(e, 2.810960958218893, 1e-12));
    assert!(close(cyclone_d50(1.8e-5, 0.05, 5.0, 20.0, 2000.0, 1.2), 2.5396151248193274e-06, 1e-12));
}

#[test]
fn flowsheet_parity() {
    // The Phase 7 recycle loop: mixer <- recycle, stoichiometric
    // reactor (10 percent per-pass conversion of component 0),
    // splitter 5 percent to product / 95 percent recycle. Fixed
    // point from the Python battery: product [31.0345, 68.9655, 0].
    use ccr::flowsheet::solve_tears;
    use ccr::units::{mixer, splitter};
    use std::cell::RefCell;
    use std::collections::HashMap;
    let rxk = ThermoRx { th: ThermoEOS::new(alkane_eos(), cp3()),
        hf: vec![0.0; 3], gf: vec![0.0; 3] };
    let streams: RefCell<HashMap<String, Stream>> = RefCell::new(HashMap::new());
    streams.borrow_mut().insert("feed".into(),
        Stream::new(vec![100.0, 0.0, 0.0], 350.0, 2.0e6));
    let evaluate = |tear: &[f64]| -> Vec<f64> {
        let mut sm = streams.borrow_mut();
        sm.insert("recycle".into(), Stream::new(
            vec![tear[0], tear[1], tear[2]], tear[3], tear[4]));
        let mixed = mixer(&rxk.th, &[sm["feed"].clone(), sm["recycle"].clone()], None);
        let (reacted, _) = reactor_stoich(&rxk, &mixed,
            &[vec![-1.0, 1.0, 0.0]], &[0.10], &[0], "isothermal",
            Some(mixed.t), None);
        let outs = splitter(&reacted, &[0.05, 0.95]);
        sm.insert("product".into(), outs[0].clone());
        let r = &outs[1];
        vec![r.flows[0], r.flows[1], r.flows[2], r.t, r.p]
    };
    let x0 = vec![50.0, 0.0, 0.0, 350.0, 2.0e6];
    let (sol, iters) = solve_tears(&evaluate, &x0, true, 1e-10, 500);
    let (_s2, iters_direct) = solve_tears(&evaluate, &x0, false, 1e-10, 3000);
    assert!(iters < iters_direct, "wegstein {iters} vs direct {iters_direct}");
    let sm = streams.borrow();
    let prod = &sm["product"];
    assert!(close(prod.flows[0], 31.0345, 1e-4), "product A {}", prod.flows[0]);
    assert!(close(prod.flows[1], 68.9655, 1e-4), "product B {}", prod.flows[1]);
    let _ = sol;
}
